    public void b(View view) {
        exec("echo \"按音量加键开启插帧守护2.0🤗\"\necho \"按音量减键恢复插帧守护2.0😚\"\nwhile true; do\n    event=$(getevent -qlc1 2>/dev/null) \n    if echo \"$event\" | grep -q KEY_VOLUMEUP; then\n        sleep 1.5\necho vivo MEMC 陌尘插帧守护 + 插帧心跳（All-in-One）\nsleep 1.5\necho 作者：陌尘\nsleep 1.5\necho \"-------------  环境检查和基础设置中… -------------\"\nsleep 1.5\nrm -f /storage/emulated/0/陌尘插帧日志.log\nINTERVAL=60\nHEART=10\nLOG_FILE=\"/storage/emulated/0/陌尘插帧日志.log\"\nPACKAGE=\"\"\nPID_FILE=\"/data/local/tmp/shizuku_mc.pid\"\nHEART_PID_FILE=\"/data/local/tmp/shizuku_mc_heart.pid\"\nexport PATH=/system/bin:/system/xbin:/data/data/com_termux/files/usr/bin:$PATH\nlog() {\n    echo \"[$(date '+%Y-%m-%d %H:%M:%S')] $1\" >> \"$LOG_FILE\"\n}\n\nshizuku_exec() {\n    cmd=\"$1\"\n    local apk_path=$(pm path moe.shizuku.privileged.api 2>/dev/null | grep package: | cut -d: -f2 | cut -d' ' -f1)\n    if [ -z \"$apk_path\" ]; then\n        apk_path=\"/data/app/moe.shizuku.privileged.api-*/base.apk\"\n    fi\n    app_process -Djava.class.path=\"$apk_path\" /system/bin --nice-name=shizuku_daemon moe.shizuku.privileged.api.Server \"$cmd\" >/dev/null 2>&1\n}\n\nif [ -f \"$PID_FILE\" ]; then\n    kill -9 $(cat \"$PID_FILE\") 2>/dev/null\n    rm \"$PID_FILE\"\nfi\nif [ -f \"$HEART_PID_FILE\" ]; then\n    kill -9 $(cat \"$HEART_PID_FILE\") 2>/dev/null\n    rm \"$HEART_PID_FILE\"\nfi\npkill -f \"shizuku_mc\" 2>/dev/null\n\nlog \"=== 脚本启动 (陌尘优化插帧守护-后台🔄) ===\"\nlog \"初始化设置：关闭智能切换，开启主流 MEMC 字段(•̀ᴗ•́)و ̑̑\"\n\nshizuku_exec \"settings put global memc_smart_switch 0\"\nlog \"已尝试关闭❎ memc_smart_switch\"\n\nfor key in memc_enabled display_memc_enabled bbk_memc; do\n    shizuku_exec \"settings put global $key 1\"\n    log \"已尝试开启🤔 $key\"\ndone\n\n(\n    while true; do\n        if [ -f \"/system/framework/vivoperfsdk.jar\" ]; then\n            am broadcast -n com.vivo.performance/com.vivo.performance.PerfService \\\n                --es cmd \"game_frame_boost\" --es value \"1\" --es pkg \"$PACKAGE\" >/dev/null 2>&1\n        else\n            shizuku_exec \"service call SurfaceFlinger 1024 i32 0 i64 500000\"\n        fi\n        sleep $HEART\n    done\n) &\nHEART_PID=$!\necho $HEART_PID > \"$HEART_PID_FILE\"\nlog \"心跳进程启动 (PID: $HEART_PID)\"\n\n# 主守护循环：定期检查 MEMC 字段是否被关，若关闭则重新开启\n(\n    log \"主守护循环启动 (每 ${INTERVAL}s 检查一次🤓)\"\n    while true; do\n        status_check=\"正常✅\"\n        for key in memc_enabled display_memc_enabled bbk_memc; do\n            current_val=$(shizuku_exec \"settings get global $key\" | grep -o '[0-9]')\n            if [ -z \"$current_val\" ]; then\n                current_val=0\n            fi\n            if [ \"$current_val\" = \"0\" ]; then\n                shizuku_exec \"settings put global $key 1\"\n                status_check=\"已修复😎\"\n                log \"检测到 $key 关闭，已重新开启😎\"\n            fi\n        done\n        if [ \"$status_check\" = \"正常\" ]; then\n            log \"守护运行中🔄... (状态: 正常✅)\"\n        else\n            log \"守护运行中🔄... (状态: $status_check)\"\n        fi\n        sleep $INTERVAL\n    done\n) &\nMAIN_PID=$!\necho $MAIN_PID > \"$PID_FILE\"\nlog \"脚本已转入后台运行 (PID: $MAIN_PID)\"\nlog \"----------------------------------------\"\necho \"已初始化日志文件\"\necho \"✅ 陌尘😋 插帧守护已启动，每 ${INTERVAL}s 检查一次，请定时清除日志，以免内存爆仓😊\"\n        \n        break\n    elif echo \"$event\" | grep -q KEY_VOLUMEDOWN; then\necho 正在暂停守护中...\nfor key in memc_enabled display_memc_enabled bbk_memc; do\n  settings put global \"$key\" 0 2>/dev/null\ndone\necho 如果已经暂停了,就不要重复点击啦😉（否则重复执行暂停脚本，只会出现本行提示）\nPID_FILE=\"/data/local/tmp/shizuku_mc.pid\"\nHEART_PID_FILE=\"/data/local/tmp/shizuku_mc_heart.pid\"\nLOG_FILE=\"/storage/emulated/0/陌尘插帧日志.log\"\n\nlog() {\n    echo \"[$(date '+%Y-%m-%d %H:%M:%S')] $1\" >> \"$LOG_FILE\"\n}\n\nlog \"=== 开始执行强制暂停😈 ===\"\n\nif [ ! -f \"$PID_FILE\" ]; then\n    log \"未找到主PID文件，可能守护进程未运行😱\"\n    exit 0\nfi\n\nMAIN_PID=$(cat \"$PID_FILE\")\nlog \"检测到主进程PID: $MAIN_PID\"\n\nif [ -f \"$HEART_PID_FILE\" ]; then\n    HEART_PID_VALUE=$(cat \"$HEART_PID_FILE\")\n    log \"检测到心跳进程🥱PID: $HEART_PID_VALUE\"\n    log \"尝试暂停心跳进程🥱 (PID: $HEART_PID_VALUE)...\"\n    kill -STOP $HEART_PID_VALUE 2>/dev/null\n    log \"心跳进程 (PID: $HEART_PID_VALUE) 已暂停😈\"\nelse\n    log \"未找到心跳PID文件，可能心跳进程未运行😱\"\nfi\n\nlog \"尝试暂停主进程 (PID: $MAIN_PID)...\"\nkill -STOP $MAIN_PID 2>/dev/null\nlog \"主进程 (PID: $MAIN_PID) 已暂停😈\"\n\nlog \"尝试关闭MEMC字段🤔\"\nshizuku_exec() {\n    cmd=\"$1\"\n    local apk_path=$(pm path moe.shizuku.privileged.api 2>/dev/null | grep package: | cut -d: -f2 | cut -d' ' -f1)\n    if [ -z \"$apk_path\" ]; then\n        apk_path=\"/data/app/moe.shizuku.privileged.api-*/base.apk\"\n    fi\n    app_process -Djava.class.path=\"$apk_path\" /system/bin --nice-name=shizuku_daemon moe.shizuku.privileged.api.Server \"$cmd\" >/dev/null 2>&1\n}\nfor key in memc_enabled display_memc_enabled bbk_memc; do\n    shizuku_exec \"settings put global $key 0\"\ndone\nlog \"所有MEMC字段已尝试关闭🤔\"\n\nmemc_enabled=$(settings get global memc_enabled 2>/dev/null)\ndisplay_memc_enabled=$(settings get global display_memc_enabled 2>/dev/null)\nbbk_memc=$(settings get global bbk_memc 2>/dev/null)\n\nif [ \"$memc_enabled\" = \"0\" ] && [ \"$display_memc_enabled\" = \"0\" ] && [ \"$bbk_memc\" = \"0\" ]; then\n    log \"所有MEMC字段当前已处于关闭状态😈\"\n    echo \"所有MEMC字段当前已处于关闭状态😈\"\nelse\n    log \"部分MEMC字段可能仍处于启用状态，请检查🤔\"\n    echo \"部分MEMC字段可能仍处于启用状态，请检查🤔\"\nfi\n\necho \"守护已暂停😈\"\nkillall sh 2>/dev/null\nlog \"=== 强制暂停执行完成😈 ===\"\nbreak\n    fi\ndone");
    }

